/****************************************************************************
 * QSPI 控制器 (D13x)
 ****************************************************************************/

#define QSPI_BASE      0x18600000
#define QSPI_VER       (QSPI_BASE + 0x000)
#define QSPI_CFG       (QSPI_BASE + 0x004)
#define QSPI_TCFG      (QSPI_BASE + 0x008)
#define QSPI_ICR       (QSPI_BASE + 0x010)
#define QSPI_ISTS      (QSPI_BASE + 0x014)
#define QSPI_FCTL      (QSPI_BASE + 0x018)
#define QSPI_FSTS      (QSPI_BASE + 0x01C)
#define QSPI_CCFG      (QSPI_BASE + 0x024)
#define QSPI_TXD       (QSPI_BASE + 0x200)
#define QSPI_RXD       (QSPI_BASE + 0x300)

/* QSPI_CFG bits */

#define QSPI_CFG_EN        (1 << 0)
#define QSPI_CFG_MASTER    (1 << 1)
#define QSPI_CFG_RST       (1 << 31)

/* QSPI_TCFG bits */

#define QSPI_TCFG_CPHA     (1 << 0)
#define QSPI_TCFG_CPOL     (1 << 1)
#define QSPI_TCFG_CS_LOW   (0 << 7)
#define QSPI_TCFG_CS_HIGH  (1 << 7)
#define QSPI_TCFG_CS_SW    (1 << 6)
#define QSPI_TCFG_START    (1 << 31)

/* QSPI_FSTS bits */

#define QSPI_FSTS_TD       (1 << 12)
#define QSPI_FSTS_TF_EMP   (1 << 5)
#define QSPI_FSTS_RF_RDY   (1 << 0)

static void d13x_spi_init(void)
{
  /* 复位控制器 */

  putreg32(QSPI_CFG_RST, QSPI_CFG);
  while (getreg32(QSPI_CFG) & QSPI_CFG_RST);

  /* 使能控制器 + 主机模式 */

  putreg32(QSPI_CFG_EN | QSPI_CFG_MASTER, QSPI_CFG);

  /* 时钟分频: SPI_CLK = src_clk / (2 * (CKDIV2 + 1))
   * src=480MHz, CKDIV2=15 → SPI_CLK = 480/(2*16) = 15MHz */

  putreg32(15, QSPI_CCFG);

  /* 传输配置: Mode 0 (CPOL=0, CPHA=0), 软件控制CS */

  putreg32(QSPI_TCFG_CS_SW | QSPI_TCFG_CS_HIGH, QSPI_TCFG);

  /* 复位 FIFO */

  putreg32((1 << 31) | (1 << 15), QSPI_FCTL);
}

static void d13x_spi_cs(int assert)
{
  uint32_t reg = getreg32(QSPI_TCFG);
  if (assert)
    reg &= ~QSPI_TCFG_CS_HIGH;
  else
    reg |= QSPI_TCFG_CS_HIGH;
  putreg32(reg, QSPI_TCFG);
}

static void d13x_spi_txrx(uint8_t *tx, uint8_t *rx, int len)
{
  int i;
  for (i = 0; i < len; i++)
  {
    /* 写入 TX FIFO */

    putreg32(tx ? tx[i] : 0, QSPI_TXD);

    /* 启动传输 */

    uint32_t tcfg = getreg32(QSPI_TCFG);
    putreg32(tcfg | QSPI_TCFG_START, QSPI_TCFG);

    /* 等待传输完成 */

    while (!(getreg32(QSPI_FSTS) & QSPI_FSTS_TD));

    /* 清除 TD 标志 (W1C) */

    putreg32(QSPI_FSTS_TD, QSPI_ISTS);

    /* 读取 RX FIFO */

    if (rx)
      rx[i] = (uint8_t)getreg32(QSPI_RXD);
  }
}

