#!/usr/bin/env python3
"""
ArtInChip BROM USB Burn Tool
通过 USB Bulk 传输烧录固件到 D13x
"""
import struct
import sys
import time
import os

try:
    import usb.core
    import usb.util
except ImportError:
    print("pip3 install pyusb")
    sys.exit(1)

VENDOR_ID = 0x33C3
PRODUCT_ID = 0x6677

EP_OUT = 0x02
EP_IN = 0x81

CMD_GET_HWINFO       = 0x00
CMD_SET_FWC_META     = 0x10
CMD_GET_BLOCK_SIZE   = 0x11
CMD_SEND_FWC_DATA    = 0x12
CMD_GET_FWC_CRC      = 0x13
CMD_GET_FWC_BURN_RES = 0x14
CMD_GET_FWC_RUN_RES  = 0x15

FWC_TYPE_SPL   = 0
FWC_TYPE_UBOOT = 1
FWC_TYPE_OS    = 2
FWC_TYPE_DATA  = 3


class AicUsbBurner:
    def __init__(self):
        self.dev = None

    def connect(self):
        print("搜索 Artinchip USB 设备...")
        self.dev = usb.core.find(idVendor=VENDOR_ID, idProduct=PRODUCT_ID)
        if self.dev is None:
            print("未找到设备! 确保板子在 BROM 升级模式 (BOOT+RESET)")
            return False

        print(f"设备: {self.dev.manufacturer} {self.dev.product}")
        try:
            self.dev.set_configuration()
        except Exception:
            pass
        print("USB 连接成功")
        return True

    def usb_write(self, data, timeout=5000):
        try:
            self.dev.write(EP_OUT, data, timeout=timeout)
            return True
        except Exception as e:
            print(f"  USB 写入失败: {e}")
            return False

    def usb_read(self, size=512, timeout=5000):
        try:
            return self.dev.read(EP_IN, size, timeout=timeout)
        except usb.core.USBTimeoutError:
            return None
        except Exception as e:
            print(f"  USB 读取失败: {e}")
            return None

    def send_cmd(self, cmd, payload=b''):
        hdr = struct.pack('<BxH', cmd, len(payload))
        full = hdr + payload
        if not self.usb_write(full):
            return False
        resp = self.usb_read(512, timeout=5000)
        if resp and len(resp) >= 1:
            return resp[0] == 0x06  # ACK
        return False

    def get_hwinfo(self):
        print("获取硬件信息...")
        if not self.send_cmd(CMD_GET_HWINFO):
            print("  失败")
            return None
        resp = self.usb_read(512, timeout=5000)
        if resp:
            data = bytes(resp)
            print(f"  信息: {data.hex()}")
            return data
        return None

    def get_block_size(self):
        print("获取块大小...")
        if not self.send_cmd(CMD_GET_BLOCK_SIZE):
            print("  失败")
            return 4096
        resp = self.usb_read(512, timeout=5000)
        if resp and len(resp) >= 4:
            bs = struct.unpack('<I', bytes(resp[:4]))[0]
            print(f"  块大小: {bs}")
            return bs
        return 4096

    def set_fwc_meta(self, fwc_type, offset, size):
        meta = struct.pack('<III', fwc_type, offset, size)
        print(f"  组件: type={fwc_type} offset=0x{offset:08X} size={size}")
        return self.send_cmd(CMD_SET_FWC_META, meta)

    def send_fwc_data(self, data):
        return self.send_cmd(CMD_SEND_FWC_DATA, data)

    def get_fwc_crc(self):
        if not self.send_cmd(CMD_GET_FWC_CRC):
            return None
        resp = self.usb_read(512, timeout=5000)
        if resp and len(resp) >= 4:
            return struct.unpack('<I', bytes(resp[:4]))[0]
        return None

    def get_fwc_burn_result(self):
        if not self.send_cmd(CMD_GET_FWC_BURN_RES):
            return False
        resp = self.usb_read(512, timeout=5000)
        if resp and len(resp) >= 4:
            return struct.unpack('<I', bytes(resp[:4]))[0] == 0
        return False

    def burn_image(self, filepath):
        filesize = os.path.getsize(filepath)
        print(f"\n固件: {filepath}")
        print(f"大小: {filesize} bytes ({filesize/1024:.1f} KB)")

        with open(filepath, 'rb') as f:
            img = f.read()

        print(f"镜像头: {img[:8]}")

        if not self.connect():
            return False

        self.get_hwinfo()
        block_size = self.get_block_size()

        print(f"\n开始传输固件...")
        offset = 0
        chunk_num = 0

        while offset < filesize:
            chunk = img[offset:offset + block_size]
            chunk_num += 1
            pct = offset * 100 // filesize
            sys.stdout.write(f"\r  块 {chunk_num} offset=0x{offset:08X} ({pct}%) ")
            sys.stdout.flush()

            if not self.set_fwc_meta(FWC_TYPE_UBOOT, offset, len(chunk)):
                print(f"\nSET_FWC_META 失败")
                return False

            if not self.send_fwc_data(chunk):
                print(f"\nSEND_FWC_DATA 失败")
                return False

            crc = self.get_fwc_crc()
            expected = sum(chunk) & 0xFFFFFFFF
            if crc is not None and crc != expected:
                print(f"\nCRC 错误: 期望 0x{expected:08X} 收到 0x{crc:08X}")
                return False

            if not self.get_fwc_burn_result():
                print(f"\n烧录失败 at 0x{offset:08X}")
                return False

            offset += block_size

        print(f"\n\n传输完成! {chunk_num} 块")
        return True


def main():
    if len(sys.argv) < 2:
        print(f"用法: {sys.argv[0]} <firmware.img>")
        sys.exit(1)

    firmware = sys.argv[1]
    if not os.path.exists(firmware):
        print(f"文件不存在: {firmware}")
        sys.exit(1)

    burner = AicUsbBurner()
    try:
        ok = burner.burn_image(firmware)
        if ok:
            print("\n烧录成功! 按 RESET 启动。")
        else:
            print("\n烧录失败!")
            sys.exit(1)
    finally:
        if burner.dev:
            usb.util.dispose_resources(burner.dev)


if __name__ == '__main__':
    main()

