u8 psram_get_psram_id(void)
{
    u32 fuse_224 = readl(EFUSE_224_REG);
    u8 psram_id = (fuse_224 & 0xff0000) >> 20;

    pr_info("fuse_224(0x19010224)=0x%x, psram_id=0x%x\n", fuse_224, psram_id);
    return psram_id;
}

