/*
 * D13x Mini Flash Writer - 极简 SPI NOR Flash 写入器
 * 通过 BROM UART 加载到 SRAM 并执行
 * 功能：通过 UART 接收固件数据，写入 SPI NOR Flash
 *
 * 协议：UART 115200 8N1
 *   主机发送: 'W' + addr(4B LE) + len(4B LE) + data...
 *   设备回复: 'O'(OK) 或 'E'(Error)
 *   主机发送: 'R' + addr(4B LE) + len(4B LE)  → 设备发送 data
 *   主机发送: 'E' + addr(4B LE) + len(4B LE)  → 擦除
 *   主机发送: 'I' → 设备回复 flash ID (3B)
 *   主机发送: 'B' → 设备重启
 */

#include <stdint.h>

/* D13x 寄存器 */
#define UART0_BASE  0x18710000
#define UART_THR    (UART0_BASE + 0x00)
#define UART_RBR    (UART0_BASE + 0x00)
#define UART_DLL    (UART0_BASE + 0x00)
#define UART_DLH    (UART0_BASE + 0x04)
#define UART_LCR    (UART0_BASE + 0x08)
#define UART_LSR    (UART0_BASE + 0x14)

#define QSPI_BASE   0x18600000
#define QSPI_TXD    (QSPI_BASE + 0x200)
#define QSPI_RXD    (QSPI_BASE + 0x300)
#define QSPI_CCFG   (QSPI_BASE + 0x024)
#define QSPI_CFG    (QSPI_BASE + 0x004)
#define QSPI_TCFG   (QSPI_BASE + 0x008)
#define QSPI_FSTS   (QSPI_BASE + 0x01C)
#define QSPI_ISTS   (QSPI_BASE + 0x014)
#define QSPI_FCTL   (QSPI_BASE + 0x018)

#define CMU_BASE    0x18020000

#define FLASH_WE    0x06
#define FLASH_RS    0x05
#define FLASH_PP    0x02
#define FLASH_SE    0x20
#define FLASH_RID   0x9F
#define FLASH_RD    0x03

static void uart_putc(char c) {
    while (!(getreg32(UART_LSR) & (1 << 5)));
    putreg32((uint32_t)c, UART_THR);
}

static int uart_getc(void) {
    while (!(getreg32(UART_LSR) & (1 << 0)));
    return (int)(getreg32(UART_RBR) & 0xFF);
}

static void uart_puts(const char *s) {
    while (*s) uart_putc(*s++);
}

static void uart_putu32(uint32_t v) {
    char buf[11];
    int i = 10;
    buf[i] = 0;
    while (v && i > 0) { buf[--i] = '0' + (v % 10); v /= 10; }
    uart_puts(buf + i);
}

static uint32_t uart_getu32(void) {
    uint32_t v = 0;
    for (int i = 0; i < 4; i++) v = (v << 8) | uart_getc();
    return v;
}

static void spi_init(void) {
    putreg32((1 << 31), QSPI_CFG);
    while (getreg32(QSPI_CFG) & (1 << 31));
    putreg32((1 << 0) | (1 << 1), QSPI_CFG);
    putreg32(15, QSPI_CCFG);
    putreg32((1 << 6) | (1 << 7), QSPI_TCFG);
    putreg32((1 << 31) | (1 << 15), QSPI_FCTL);
}

static void spi_cs(int on) {
    uint32_t v = getreg32(QSPI_TCFG);
    if (on) v &= ~(1 << 7); else v |= (1 << 7);
    putreg32(v, QSPI_TCFG);
}

static uint8_t spi_xfer(uint8_t tx) {
    putreg32(tx, QSPI_TXD);
    uint32_t t = getreg32(QSPI_TCFG);
    putreg32(t | (1u << 31), QSPI_TCFG);
    while (!(getreg32(QSPI_FSTS) & (1 << 12)));
    putreg32((1 << 12), QSPI_ISTS);
    return (uint8_t)getreg32(QSPI_RXD);
}

static uint32_t flash_read_id(void) {
    uint8_t id[3];
    spi_cs(1);
    spi_xfer(FLASH_RID);
    for (int i = 0; i < 3; i++) id[i] = spi_xfer(0);
    spi_cs(0);
    return (id[0] << 16) | (id[1] << 8) | id[2];
}

static void flash_write_enable(void) {
    spi_cs(1); spi_xfer(FLASH_WE); spi_cs(0);
}

static void flash_wait_busy(void) {
    uint8_t st;
    do {
        spi_cs(1);
        spi_xfer(FLASH_RS);
        st = spi_xfer(0);
        spi_cs(0);
    } while (st & 0x01);
}

static void flash_erase_sector(uint32_t addr) {
    flash_write_enable();
    spi_cs(1);
    spi_xfer(FLASH_SE);
    spi_xfer((addr >> 16) & 0xFF);
    spi_xfer((addr >> 8) & 0xFF);
    spi_xfer(addr & 0xFF);
    spi_cs(0);
    flash_wait_busy();
}

static void flash_write_page(uint32_t addr, uint8_t *data, int len) {
    flash_write_enable();
    spi_cs(1);
    spi_xfer(FLASH_PP);
    spi_xfer((addr >> 16) & 0xFF);
    spi_xfer((addr >> 8) & 0xFF);
    spi_xfer(addr & 0xFF);
    for (int i = 0; i < len; i++) spi_xfer(data[i]);
    spi_cs(0);
    flash_wait_busy();
}

static void flash_read(uint32_t addr, uint8_t *buf, int len) {
    spi_cs(1);
    spi_xfer(FLASH_RD);
    spi_xfer((addr >> 16) & 0xFF);
    spi_xfer((addr >> 8) & 0xFF);
    spi_xfer(addr & 0xFF);
    for (int i = 0; i < len; i++) buf[i] = spi_xfer(0);
    spi_cs(0);
}

static uint8_t buf[4096];

void _start(void) {
    /* 初始化 UART (假设 BROM 已设置好) */
    /* 初始化 SPI */
    spi_init();

    uart_puts("\r\nD13x MiniFlash v1.0\r\n");

    uint32_t fid = flash_read_id();
    uart_puts("Flash ID: 0x");
    for (int i = 5; i >= 0; i--) {
        int n = (fid >> (i * 4)) & 0xF;
        uart_putc(n < 10 ? '0' + n : 'A' + n - 10);
    }
    uart_puts("\r\n");

    while (1) {
        int cmd = uart_getc();

        switch (cmd) {
        case 'W': { /* Write to flash */
            uint32_t addr = uart_getu32();
            uint32_t len = uart_getu32();
            uart_puts("W: addr=0x");
            uart_putu32(addr);
            uart_puts(" len=");
            uart_putu32(len);
            uart_puts("\r\n");

            uint32_t off = 0;
            while (off < len) {
                uint32_t chunk = len - off;
                if (chunk > 4096) chunk = 4096;
                for (uint32_t i = 0; i < chunk; i++)
                    buf[i] = uart_getc();
                flash_erase_sector(addr + off);
                uint32_t p = 0;
                while (p < chunk) {
                    uint32_t pg = chunk - p;
                    if (pg > 256) pg = 256;
                    flash_write_page(addr + off + p, buf + p, pg);
                    p += pg;
                }
                off += chunk;
                uart_putc('.');
            }
            uart_puts(" OK\r\n");
            uart_putc('O');
            break;
        }
        case 'R': { /* Read from flash */
            uint32_t addr = uart_getu32();
            uint32_t len = uart_getu32();
            flash_read(addr, buf, len > 4096 ? 4096 : len);
            for (uint32_t i = 0; i < len && i < 4096; i++)
                uart_putc(buf[i]);
            break;
        }
        case 'E': { /* Erase flash */
            uint32_t addr = uart_getu32();
            uint32_t len = uart_getu32();
            for (uint32_t off = 0; off < len; off += 4096) {
                flash_erase_sector(addr + off);
                uart_putc('.');
            }
            uart_puts(" OK\r\n");
            uart_putc('O');
            break;
        }
        case 'I': { /* Read flash ID */
            uint32_t id = flash_read_id();
            uart_putc((id >> 16) & 0xFF);
            uart_putc((id >> 8) & 0xFF);
            uart_putc(id & 0xFF);
            break;
        }
        case 'B': { /* Reboot */
            uart_puts("Rebooting...\r\n");
            putreg32(0x1, CMU_BASE + 0x0900); /* watchdog reset */
            while (1);
            break;
        }
        case 'P': { /* Ping */
            uart_putc('P');
            break;
        }
        }
    }
}

